/* Machine-readable reason catalogue for the compatibility policy (r1).
 * severity: info (recorded, no effect) < unverified < unsupported < reject.
 * A link's decision is set by its most severe reason:
 *   no reason above info -> compatible; unverified -> unverified;
 *   unsupported -> unsupported; reject -> rejected.
 * owner names who, outside this engine, would have to decide or supply evidence. */

export const OWNERS = Object.freeze({
  admission: 'root-admission',
  integration: 'root-integration',
  adapter: 'exchange-adapter-owner',
  importer: 'importer-mapping-step',
  model: 'scientific-model-owner',
  rights: 'rights-owner',
  calibration: 'calibration-owner',
  clock: 'clock-synchronization-owner',
  verifier: 'qualified-pairing-verifier',
});

const R = (severity, text, owner) => Object.freeze(owner ? { severity, text, owner } : { severity, text });
const O = OWNERS;

